     parts=n.args[0].elts
     if len(parts)==3 and isinstance(parts[0],ast.Constant) and parts[0].value=='ssh' and isinstance(parts[1],ast.Constant) and isinstance(parts[1].value,str) and not parts[1].value.startswith('-'):
