"""Explicit local external-input flow into interpreter code; no execution or broad sanitizer claims."""
import ast,re
INTERPRETERS={'sh':{'-c','-lc'},'bash':{'-c','-lc'},'dash':{'-c'},'python':{'-c'},'python3':{'-c'},'node':{'-e','--eval'}}
