    for attr in ('body','orelse','finalbody'):
     if getattr(st,attr,None):walk(getattr(st,attr),dict(env))
 walk(tree.body,{})
 unique=lambda xs:list({(x['path'],x['line'],x['kind']):x for x in xs}.values())
 return {'findings':unique(findings),'calls':unique(calls)}
def self_test():
